//! Parity tests against the Go original (`github.com/junhinhow/charm-spinner`).
//!
//! The golden files are generated by the Go program in
//! `reference/go/charm-spinner/cmd/parity`, which prints the very same data
//! as this test builds from the Rust API:
//!
//! ```text
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-spinner/tests/golden/spinners.txt -- \
//!     go run ./reference/go/charm-spinner/cmd/parity report
//!
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-spinner/tests/golden/spinners_dump.txt -- \
//!     go run ./reference/go/charm-spinner/cmd/parity dump
//! ```
//!
//! `spinners.txt` is the human readable report (compared with
//! [`assert_golden`]) and `spinners_dump.txt` is the raw byte dump, compared
//! byte-for-byte. The latter is the strong guarantee: every one of the 204
//! frames of the 30 spinners must be exactly the same sequence of bytes as
//! in the Go source.

use std::fmt::Write as _;

use charm_parity::assert_golden;
use charm_spinner::all;

/// Separates two frames inside the raw dump (U+0001).
const UNIT: &str = "\u{1}";

/// Separates two spinners inside the raw dump (U+0002).
const RECORD: u8 = 0x02;

/// Builds the human readable report, mirroring the Go parity program.
fn build_report() -> String {
    let mut out = String::new();
    for (name, spinner) in all() {
        let _ = writeln!(out, "spinner={name}");
        let _ = writeln!(out, "interval_ms={}", spinner.interval.as_millis());
        let _ = writeln!(out, "frames={}", spinner.frames.join(UNIT));
        for index in 0..spinner.frames.len() {
            let _ = writeln!(out, "render[{index}]={}", spinner.render(index));
        }
    }
    out
}

/// Builds the raw byte dump, mirroring the Go parity program.
fn build_dump() -> Vec<u8> {
    let mut out = Vec::new();
    for (name, spinner) in all() {
        let mut fields: Vec<String> = Vec::with_capacity(spinner.frames.len() + 2);
        fields.push(name.to_owned());
        fields.push(spinner.interval.as_millis().to_string());
        fields.extend(spinner.frames.iter().cloned());
        out.extend_from_slice(fields.join(UNIT).as_bytes());
        out.push(RECORD);
    }
    out
}

/// Fails with a precise report when two byte sequences diverge.
fn assert_bytes_identical(expected: &[u8], actual: &[u8]) {
    if expected == actual {
        return;
    }
    let mut offset = 0;
    while offset < expected.len() && offset < actual.len() && expected[offset] == actual[offset] {
        offset += 1;
    }
    panic!(
        "divergencia byte-a-byte no offset {offset}: esperado {:#04X}, obtido {:#04X}\n\
         --- esperado (Go) ---\n{}\n\
         --- obtido (Rust) ---\n{}\n\
         --- fim ---",
        expected.get(offset).copied().unwrap_or_default(),
        actual.get(offset).copied().unwrap_or_default(),
        String::from_utf8_lossy(expected),
        String::from_utf8_lossy(actual)
    );
}

#[test]
fn spinners_match_the_go_original() {
    assert_golden("spinners", &build_report());
}

#[test]
fn spinner_dump_is_byte_identical_to_the_go_original() {
    let golden = std::fs::read(charm_parity::golden_path("spinners_dump")).unwrap_or_else(|err| {
        panic!(
            "golden file ausente: {} ({err}).\nGere-o com:\n  \
             cargo run -p charm-parity --bin parity -- gen \
             crates/charm-spinner/tests/golden/spinners_dump.txt -- \
             go run ./reference/go/charm-spinner/cmd/parity dump",
            charm_parity::golden_path("spinners_dump").display()
        )
    });
    assert_bytes_identical(&golden, &build_dump());
}

#[test]
fn spinner_dump_matches_the_golden_harness() {
    let dump = build_dump();
    let text = String::from_utf8(dump).expect("o dump deve ser UTF-8 valido");
    assert_golden("spinners_dump", &text);
}

#[test]
fn every_spinner_is_present_with_its_exact_name() {
    let spinners = all();
    assert_eq!(spinners.len(), 30);
    for name in [
        "Arrow",
        "Balloon",
        "Bar",
        "Bounce",
        "Christmas",
        "Circle",
        "Clock",
        "DNA",
        "Dots",
        "Earth",
        "Fading",
        "Fire",
        "Flip",
        "Grow",
        "Hearts",
        "Layer",
        "Line",
        "Matrix",
        "Monkey",
        "Moon",
        "Noise",
        "Orbit",
        "Pulse",
        "Rocket",
        "Soccer",
        "Square",
        "Star",
        "Toggle",
        "Triangle",
        "Weather",
    ] {
        let spinner = spinners
            .get(name)
            .unwrap_or_else(|| panic!("spinner ausente: {name}"));
        assert!(!spinner.frames.is_empty(), "{name} nao possui frames");
        assert!(
            spinner.interval.as_millis() > 0,
            "{name} possui intervalo invalido"
        );
    }
}

#[test]
fn render_cycles_with_wrap_around() {
    for (name, spinner) in all() {
        let total = spinner.frames.len();
        for index in 0..(total * 3) {
            assert_eq!(
                spinner.render(index),
                spinner.render(index % total),
                "{name} nao faz wrap-around"
            );
        }
        assert_eq!(spinner.render(0), spinner.render(total), "{name}");
        assert!(!spinner.render(0).is_empty(), "{name} renderizou vazio");
    }
}
